def first_player_wins_stone_game(piles):
 dp=piles[:]
 for length in range(2,len(piles)+1):
  for left in range(len(piles)-length+1):
   right=left+length-1;dp[left]=max(piles[left]-dp[left+1],piles[right]-dp[left])
 return dp[0]>0

